/* TNM World Wrestling Report: PPW (Power Pro Wrestling · USWA Wrestling Academy).
   Everything the site shows for this promotion lives in this file. */

P.pp = {"short": "PPW", "nav": "Power Pro", "name": "Power Pro Wrestling · USWA Wrestling Academy", "home": "Nashville, TN", "c": "var(--pp)", "asOf": "1991-06-30", "status": "Two cards in at the Nashville Fairgrounds. Chris Jericho is the first Power Pro Champion, Michael Modest has been promised the first shot, and the third card, Power Hour, was taped before the Bash and airs July 28.", "stat": ["$1,750", "gate, First Strike (350 at $5, est.)"], "titles": [["Power Pro Heavyweight", "Chris Jericho", "Won the vacant title 6/30 over Bagwell (German suplex). First defense on Power Hour (taped, airs 7/28)."], ["Power Pro Tag Team", "To establish", "The Thrillseekers, Armstrong & Duncum Jr. and Steel & Hughes are the obvious candidates."]], "factions": [["The Trainers", "Rocky Johnson (head trainer, on-air authority), Ron Bass and Buzz Sawyer, who also wrestle. Bill Watts consults."], ["The Thrillseekers", "Chris Jericho & Lance Storm. Turned down Buzz Sawyer as their manager on opening night."], ["Armstrong & Duncum Jr.", "Brad Armstrong and Bobby Duncum Jr. New to the academy."], ["Paul Bearer", "On-air only. To establish."]], "stories": [["The First Champion", "Chris Jericho beat Ron Bass and Marcus Alexander Bagwell on June 30 to win the vacant Power Pro Heavyweight Title. He's 2–0 and one half of the Thrillseekers with Lance Storm.", "pp-the-first-champion-0630"], ["Modest Wants His Shot", "Michael Modest is 3–0. He won the Genesis tournament with the title not on the line, beat Simon Diamond again at First Strike, and confronted Jericho. Rocky Johnson promised him the first shot.", "pp-modest-wants-shot-0630"], ["Power Hour Is in the Can", "The third card was taped at the Fairgrounds before the Great American Bash and airs July 28. New names have been seen around the academy.", "pp-power-hour-in-the-can"], ["The Gate Problem", "Genesis drew 425 and First Strike drew 350. The academy needs a draw."]], "desk": ["Card 3 (Power Hour) is in the can and airs 7/28. Results stay under wraps until then.", "Card 4 is late August. It needs a draw: the legends autograph session from the Genesis notes?", "Michael Modest and Ace Steel no-showed the Power Hour taping. Explain it on-air or move on. Modest is still owed his title shot.", "Marcus Bagwell is out 10 cards (neck). At one show a month, that's most of a year. Steven Dunn out 1 card.", "Chris Benoit hurt his neck in New Japan 7/14 (as the Pegasus Kid). Check him before Card 4.", "Who gets the first USWA call-up? Not everyone will.", "Excursions: which promotions take the young lions?", "Explain Paul Bearer.", "Tag titles?", "New intake every 6 months."], "roster": [["Chris Jericho", "Champion · 2–0 · Thrillseekers · 9 cards left (TNM 7/24)"], ["Michael Modest", "3–0 · 9 cards left (TNM 7/24)"], ["Mike Awesome", "1–2 · 9 cards left (TNM 7/24)"], ["Lance Storm", "1–0 · Thrillseekers · 9 cards left (TNM 7/24)"], ["Chris Benoit", "INJ:Neck (NJPW 7/14, as Pegasus Kid) · 31 cards left (TNM 7/24)"], ["The Lightning Kid", "New · also CMLL · 11 cards left (TNM 7/24)"], ["Brad Armstrong", "New · 29 cards left (TNM 7/24)"], ["Bobby Duncum Jr.", "New · 44 cards left (TNM 7/24)"], ["Brian Armstrong", "New · Bob Armstrong's son · 12 cards left (TNM 7/24)"], ["Leatherface", "New · 11 cards left (TNM 7/24)"], ["Ace Steel", "1–1 · 9 cards left (TNM 7/24)"], ["Devon Hughes", "1–0 · 10 cards left (TNM 7/24)"], ["Judge Dread", "New · 11 cards left (TNM 7/24)"], ["Johnny B. Badd", "New · 10 cards left (TNM 7/24)"], ["Tatanka", "New · 10 cards left (TNM 7/24)"], ["Bart Gunn", "0–1 · 9 cards left (TNM 7/24)"], ["Simon Diamond", "0–2 · 9 cards left (TNM 7/24)"], ["Marcus Alexander Bagwell", "INJ:Neck, out 10 cards (hurt at the Power Hour taping) · 1–1"], ["Steven Dunn", "INJ:Neck, out 1 card (hurt at the Power Hour taping)"], ["Tony DeVito", "Student, re-enrolled 7/91 · 2–1, Genesis finalist"], ["Mike Quackenbush", "Student, re-enrolled 7/91 · 0–1"], ["Glenn Gilbertti", "Student, re-enrolled 7/91 · 0–1"], ["Rocky Johnson", "Head trainer · 9 cards left (TNM 7/24)"], ["Ron Bass", "Trainer · 0–1 · 9 cards left (TNM 7/24)"], ["Buzz Sawyer", "Trainer · 0–1 · 9 cards left (TNM 7/24)"], ["Bill Watts", "Consultant · 10 cards left (TNM 7/24)"], ["Paul Bearer", "On-air only"]], "departures": [], "rgroups": [["Staff", "Run the school and the shows.", ["Rocky Johnson", "Ron Bass", "Buzz Sawyer", "Bill Watts", "Paul Bearer"]], ["Veterans", "Established pros brought in so the students have someone to learn from. Paid per show.", ["Brad Armstrong", "Bobby Duncum Jr.", "Leatherface"]], ["Graduates", "The Young Lions: signed talent who have finished training. They headline the cards and are the ones loaned to other promotions.", ["Chris Jericho", "Michael Modest", "Mike Awesome", "Chris Benoit", "Lance Storm", "The Lightning Kid", "Johnny B. Badd", "Tatanka", "Marcus Alexander Bagwell", "Bart Gunn"]], ["Students", "The class of 1991: ten students at $2,500 tuition each. They get ring time on the cards; those on the pay scale also get a small fee when they work. One place in the class is To establish.", ["Ace Steel", "Devon Hughes", "Judge Dread", "Simon Diamond", "Steven Dunn", "Brian Armstrong", "Tony DeVito", "Mike Quackenbush", "Glenn Gilbertti"]]]};

E.push(...[{"d": "1991-05-10", "p": "pp", "city": "Nashville, TN", "venue": "Fairgrounds", "type": "Genesis: A New Beginning", "gate": "425", "rate": "**", "m": [["Title tournament R1: Michael Modest vs. Simon Diamond", "Modest (short lariat)", "**"], ["R1: Mike Awesome vs. Mike Quackenbush", "Awesome (inverted power bomb)", "**"], ["R1: Tony DeVito vs. Ace Steel", "DeVito (moonsault)", "*3/4"], ["Semifinal: Michael Modest vs. TBA", "Modest by default (no-show)", ""], ["Semifinal: Tony DeVito vs. Mike Awesome", "DeVito by DQ", "**1/4"], ["Final (title not on the line): Modest vs. DeVito", "Modest (flying elbowdrop)", "**1/2"], ["Lance Storm vs. Buzz Sawyer", "Storm by count-out", "*1/4"]], "n": ["The USWA Wrestling Academy opens. Trainers: Rocky Johnson (head), Ron Bass, Buzz Sawyer.", "The Thrillseekers turn down Sawyer as manager."]}, {"d": "1991-06-30", "p": "pp", "city": "Nashville, TN", "venue": "Fairgrounds", "type": "First Strike (first \"Level Up\" event)", "gate": "350", "rate": "**3/4", "big": 1, "m": [["Semifinal: Chris Jericho vs. Ron Bass", "Jericho (roll-up)", "**3/4"], ["Semifinal: Marcus Alexander Bagwell vs. Mike Awesome", "Bagwell (flying cross body)", "***"], ["Ace Steel & Devon Hughes vs. Bart Gunn & Glenn Gilbertti", "Steel pins Gilbertti (Northern Lights)", "**1/4"], ["Michael Modest vs. Simon Diamond", "Modest (fisherman suplex)", "***1/4"], ["Vacant Power Pro Heavyweight Title: Jericho vs. Bagwell", "Jericho (German suplex). New champion", "**1/2"]], "n": ["Modest confronts Jericho and demands the first title shot.", "Announced for Power Hour: Modest vs. Jericho for the title, Awesome vs. Bass, Bagwell vs. Steel."]}, {"d": "1991-07-28", "p": "pp", "city": "Nashville, TN", "venue": "Fairgrounds", "type": "Power Hour", "gate": "200 · $1,000", "rate": "*3/4", "big": 1, "m": [["The Lightning Kid vs. Judge Dread", "Lightning Kid (moonsault). Both debut", "***1/2"], ["Chris Benoit vs. Johnny B. Badd", "Benoit (Northern Lights). Benoit debuts", "***"], ["Brad Armstrong & Bobby Duncum Jr. vs. Devon Hughes & Buzz Sawyer", "Armstrong pins Sawyer (cross body)", "**3/4"], ["Four corners: Awesome vs. Storm vs. Bagwell vs. Tatanka", "Awesome (last out: Tatanka by DQ). 31:35", "**"], ["Leatherface vs. Steven Dunn", "Leatherface (power bomb). Paul Bearer interferes", "-*1/2"], ["Power Pro Title: Chris Jericho (c) vs. Bart Gunn", "Jericho retains (Lion Tamer)", "***1/2"]], "n": ["No-shows: Michael Modest, Ace Steel.", "Injured: Bagwell (neck, ~10 cards), Steven Dunn (neck, ~1 card)."], "taped": "Taped before the Great American Bash · airs 7/28"}]);

Object.assign(ARTICLES, {"pp-young-lions-abroad": {"p": "pp", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Nashville Report", "kicker": "Power Pro · Backstage", "title": "Young Lions Abroad", "dek": "The Power Pro trainers want to send their students overseas. The Lightning Kid is already in Mexico City.", "body": [["p", "The Power Pro trainers said at First Strike that they were working with promotions around the world to send their young lions on excursion. That's already happening. The Lightning Kid made his CMLL debut at Arena México on July 12, losing to Art Barr in two falls but getting over with the crowd, and he's booked in Acapulco on the 17th against Jushin Liger and the Blue Blazer."], ["p", "It's the same model New Japan and All Japan have used for years: send the kids to Mexico or Europe, let them learn a different style in front of crowds that don't know them, and bring them home as something new. Rocky Johnson has reportedly made calls to CMLL and to the UK, where All Star Wrestling's holiday camp season could use young babyfaces."], ["h", "Who's next"], ["p", "Chris Benoit, the academy's newest technician, is the obvious candidate. He's also listed by New Japan as the Pegasus Kid and has a junior title match with Jushin Liger at Sumo Hall on July 30, so he's already more traveled than anyone else in the academy. Lance Storm and Chris Jericho, the Thrillseekers, are the other names mentioned, although Jericho is the Power Pro Champion and the office isn't going to let him leave with the belt."]], "facts": [["Already abroad", "The Lightning Kid (CMLL)"], ["Next CMLL date", "Acapulco, 7/17"], ["Next candidate", "Chris Benoit"], ["Possible destinations", "CMLL, All Star Wrestling"], ["Staying home", "Chris Jericho (champion)"]], "factTitle": "The Program"}, "pp-jericho-keeps-the-belt": {"airs": "1991-07-28", "p": "pp", "news": 1, "region": "Nashville Report", "by": "Newsletter staff", "date": "1991-07-29", "kicker": "Power Pro · Power Hour · Nashville, July 28", "title": "Jericho Keeps the Belt", "dek": "Chris Jericho made Bart Gunn pass out in the Lion Tamer and is still the only Power Pro Champion there has ever been. The man who was supposed to be his challenger didn't show up.", "body": [["p", "The third Power Pro card closed with the right man holding the belt. Chris Jericho beat Bart Gunn in 10:02 at ***1/2, and Gunn never tapped. He passed out in the Lion Tamer, and the referee stopped it."], ["p", "Jericho has been the best thing about this academy since the second show. He beat Ron Bass with a roll-up in the First Strike semifinal, then beat Marcus Alexander Bagwell with a German suplex to win the vacant title on June 30. He's 3–0, he's the champion, and he's one half of the Thrillseekers with Lance Storm."], ["h", "The wrong challenger"], ["p", "Gunn was a fill-in. The title match announced on June 30 was Jericho against Michael Modest, who had gone 3–0 and demanded the first shot. Modest didn't show. Neither did Ace Steel. None of the three matches announced at First Strike took place, and the office had to rebuild the card on the night."], ["p", "Gunn is now 0–2 in Power Pro, but he went ten minutes with the champion in the second-best match of the show. That's more than he'd done before."]], "facts": [["Champion", "Chris Jericho"], ["Won", "6/30/91 vs. Bagwell (German suplex)"], ["Defense 1", "7/28/91 vs. Bart Gunn (Lion Tamer), ***1/2"], ["Record", "3–0"]], "factTitle": "The Champion"}, "pp-where-was-modest": {"airs": "1991-07-28", "p": "pp", "news": 1, "region": "Nashville Report", "by": "Newsletter staff", "date": "1991-07-29", "kicker": "Power Pro · No-Show", "title": "Where Was Michael Modest?", "dek": "He won the first tournament, called out the champion and was promised the first title shot. Then he didn't come to Nashville.", "body": [["p", "Michael Modest has been the most consistent winner in Power Pro. He pinned Simon Diamond with a short lariat in the first round at Genesis, got a bye in the semifinal when his opponent no-showed, and pinned Tony DeVito with a flying elbowdrop in the final. The title wasn't on the line that night, which is why Jericho, not Modest, ended up as the first champion."], ["p", "At First Strike, Modest beat Diamond again (***1/4, the best singles match on that card), then confronted Jericho and demanded the first shot. Rocky Johnson gave it to him for July. Modest vs. Jericho headlined the announced card."], ["p", "On July 28 he wasn't there. Ace Steel, who won a tag match at First Strike, wasn't either. The office hasn't said why."], ["h", "What now"], ["p", "Modest is 3–0 and still the logical challenger. The question is whether Power Pro holds the no-show against him on-air or quietly rebooks the match for August. At one show a month, a missed date costs a wrestler a month of momentum."]], "facts": [["Record", "3–0"], ["5/10", "d. Simon Diamond, d. Tony DeVito (Genesis tournament)"], ["6/30", "d. Simon Diamond, ***1/4"], ["7/28", "No-show (also: Ace Steel)"]], "factTitle": "Michael Modest"}, "pp-six-new-faces": {"airs": "1991-07-28", "p": "pp", "news": 1, "region": "Nashville Report", "by": "Newsletter staff", "date": "1991-07-29", "kicker": "Power Pro · New Arrivals", "title": "Six New Faces", "dek": "Power Hour brought six debuts, and two of them stole the show before the main event.", "body": [["p", "The best match at Power Hour was the opener. The Lightning Kid and Judge Dread, both debuting, went 19:27, and Lightning Kid won with a moonsault at ***1/2. Nobody expected that from the first match on a card that drew 200 people."], ["p", "Chris Benoit debuted next and pinned Johnny B. Badd with a Northern Lights suplex at ***. Benoit is the most polished rookie the academy has had."], ["p", "Brad Armstrong and Bobby Duncum Jr. debuted as a team and beat Devon Hughes and trainer Buzz Sawyer when Armstrong hit a flying cross body on Sawyer (**3/4). Armstrong is a veteran hand, there to steady the kids."], ["p", "Leatherface pinned Steven Dunn with a power bomb, but the match was the worst on the card (-*1/2), and the only thing anyone remembers is Paul Bearer getting involved against Leatherface. What Bearer is doing in Nashville is anyone's guess."], ["h", "The rest of the card"], ["p", "Mike Awesome won the four corners over Lance Storm, Bagwell and Tatanka. Tatanka eliminated Storm with the End of the Trail, Awesome put Bagwell away with the Awesome Bomb, and then Tatanka got himself disqualified. Bagwell came out of it with a neck injury that will keep him out about 10 cards."]], "facts": [["The Lightning Kid", "d. Judge Dread, ***1/2"], ["Chris Benoit", "d. Johnny B. Badd, ***"], ["Armstrong & Duncum Jr.", "d. Hughes & Sawyer, **3/4"], ["Leatherface", "d. Steven Dunn, -*1/2"]], "factTitle": "The Debuts"}, "pp-the-gate-problem": {"airs": "1991-07-28", "p": "pp", "news": 1, "region": "Nashville Report", "by": "Newsletter staff", "date": "1991-07-29", "kicker": "Power Pro · Business", "title": "The Gate Problem", "dek": "Three shows at the Nashville Fairgrounds, three smaller crowds. Power Hour drew 200 at $5 a head.", "body": [["p", "Genesis drew 425 on May 10. First Strike drew 350 on June 30. Power Hour drew 200 on July 28, at $5 a ticket, for a $1,000 gate. The card ratings have gone the same way: **, then **3/4, then *3/4."], ["p", "Nobody expects a training school to make money at the door. Power Pro is the USWA's Wrestling Academy, with Rocky Johnson as head trainer, Ron Bass and Buzz Sawyer working alongside him, and Bill Watts consulting. The point is to turn out wrestlers. But an empty building is hard on rookies who are supposed to be learning how to work a crowd."], ["h", "Ideas on the table"], ["p", "The Genesis notes promised a pre-show autograph session with territory legends, and that may be the easiest fix. Getting the champion and the no-shows back on the same card would help too. The academy runs once a month, so the next chance is late August."], ["p", "The bigger plan hasn't changed. A new class comes in every six months, and after six months of training, students can debut in enhancement matches on syndicated TV or go overseas on excursion. Not everyone will be called up to the USWA."]], "facts": [["5/10 Genesis", "425 · **"], ["6/30 First Strike", "350 · **3/4"], ["7/28 Power Hour", "200 · $1,000 · *3/4"], ["Next", "Late August 1991"]], "factTitle": "The Gate"}, "pp-observer-notes-watts": {"airs": "1991-07-28", "p": "pp", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-29", "region": "Nashville Report", "kicker": "Power Pro · Backstage Notes", "title": "Backstage Notes: The Watts Plan", "dek": "Bill Watts wants to rent out the academy's students to promotions overseas.", "factTitle": "Filed from", "facts": [["Consultant", "Bill Watts"], ["Head trainer", "Rocky Johnson"], ["Last show", "Power Hour, 7/28 · 200 · $1,000"]], "body": [["h", "Nashville Fairgrounds"], ["p", "Bill Watts came into the academy as a consultant with one big idea: loan Power Pro students to overseas promotions for a fee. The promotion that books a student pays the academy, and the student comes back seasoned. Rocky Johnson and the trainers decide who's ready, and Watts handles the business side. Partners and fees aren't set. All Japan, New Japan, CMLL and All Star Wrestling are the obvious possibilities."]]}});

CONTRACTS.pp = {"basis": "Per show", "unit": "per appearance", "revenue": "Nashville Fairgrounds cards: Genesis drew 425, First Strike 350, Power Hour 200 at $5 ($1,000). About $1,000–$2,000 a card. Academy tuition: ten students at $2,500 a class, a new class every six months (about $4,167 a month), the company's biggest income.", "target": "Power Pro is the USWA's development brand, so it runs at a loss: a typical card pays about $600–700 in talent. The USWA covers the difference.", "how": "Flat fee for each card worked. Trainers who also wrestle (Ron Bass, Buzz Sawyer) get their trainer fee for the night. Bill Watts is paid per card as a consultant. Managers and announcers are on the same scale. Students pay $2,500 tuition for a six-month class (ten in the class of 1991); the C-tier fee is what a student gets for working a card.", "classes": [], "rows": [["A", "Chris Jericho", 60, "Power Pro Heavyweight Champion"], ["A", "Michael Modest", 45, ""], ["A", "Mike Awesome", 45, ""], ["A", "Chris Benoit", 45, "Debuted 7/28"], ["A", "Lance Storm", 40, "Thrillseekers"], ["B", "The Lightning Kid", 35, "Also CMLL"], ["B", "Brad Armstrong", 35, ""], ["B", "Johnny B. Badd", 35, ""], ["B", "Tatanka", 35, ""], ["B", "Marcus Alexander Bagwell", 30, "Injured, neck"], ["B", "Bobby Duncum Jr.", 30, ""], ["B", "Leatherface", 30, ""], ["B", "Bart Gunn", 30, ""], ["C", "Ace Steel", 25, "Student"], ["C", "Devon Hughes", 25, "Student"], ["C", "Judge Dread", 25, "Student"], ["C", "Simon Diamond", 25, "Student"], ["C", "Steven Dunn", 20, "Student · Injured, neck"], ["C", "Brian Armstrong", 20, "Student · Bob Armstrong's son"], ["C", "Tony DeVito", 20, "Student, re-enrolled 7/91"], ["C", "Mike Quackenbush", 20, "Student, re-enrolled 7/91"], ["C", "Glenn Gilbertti", 20, "Student, re-enrolled 7/91"], ["S", "Bill Watts", 100, "Consultant"], ["S", "Rocky Johnson", 75, "Head trainer, on-air authority"], ["S", "Ron Bass", 40, "Trainer, also wrestles"], ["S", "Buzz Sawyer", 40, "Trainer, also wrestles"], ["M", "Paul Bearer", 40, "On-air only"]], "total": 990, "check": "Power Hour paid $775 against a $1,000 gate (78%). That loss is the cost of developing talent for the USWA."};

FINANCE.pp = {"period": "Per show", "payBasis": "Per show", "rows": [{"d": "1991-05-10", "show": "Nashville, TN · Genesis: A New Beginning", "cls": "Regular", "gate": 2125, "payroll": 395, "note": "8 on the card; gate estimated at $5 a ticket"}, {"d": "1991-06-30", "show": "Nashville, TN · First Strike (first \"Level Up\" event)", "cls": "Regular", "gate": 1750, "payroll": 500, "note": "11 on the card; gate estimated at $5 a ticket"}, {"d": "1991-07-02", "show": "Nashville, TN · Power Hour", "cls": "Regular", "gate": 1000, "payroll": 775, "note": "19 on the card. Ran 7/2, before Benoit left for New Japan (date to confirm). Not a TV taping"}], "other": [{"d": "1991-07-04", "stream": "Talent loan fees", "amt": 850, "note": "NJPW excursion deal for Chris Benoit (Pegasus Kid): $750 placement fee on his Summer Crush debut, Tokyo, plus $100 a date"}, {"d": "1991-07-06", "stream": "Talent loan fees", "amt": 100, "note": "Pegasus Kid, NJPW Osaka"}, {"d": "1991-07-10", "stream": "Talent loan fees", "amt": 100, "note": "Pegasus Kid, NJPW Nagoya"}, {"d": "1991-07-13", "stream": "Talent loan fees", "amt": 100, "note": "Pegasus Kid, NJPW Abashiri"}, {"d": "1991-07-14", "stream": "Talent loan fees", "amt": 100, "note": "Pegasus Kid, NJPW Hiroshima (neck injury; excursion over)"}, {"d": "1991-07-12", "stream": "Talent loan fees", "amt": 850, "note": "CMLL excursion deal for the Lightning Kid: $750 placement fee on his Arena México debut plus $100 a date"}, {"d": "1991-07-17", "stream": "Talent loan fees", "amt": 100, "note": "Lightning Kid, CMLL Acapulco"}, {"d": "1991-07-19", "stream": "Talent loan fees", "amt": 100, "note": "Lightning Kid, CMLL Arena México (trios)"}, {"d": "1991-07-21", "stream": "Talent loan fees", "amt": 100, "note": "Lightning Kid, CMLL Puebla"}], "note": "Genesis and First Strike gates are estimates (attendance × $5). Rocky Johnson and Bill Watts are paid for every card."};

