Object.assign(ARTICLES, {"pp-the-first-champion-0630": {"p": "pp", "news": 1, "by": "Newsletter staff", "date": "1991-06-30", "region": "Nashville Report", "kicker": "Power Pro · Nashville Fairgrounds, June 30", "title": "The First Champion", "dek": "Chris Jericho beat Ron Bass and Marcus Alexander Bagwell on one night to become the first Power Pro Heavyweight Champion.", "body": [["p", "Power Pro crowned its first champion at First Strike, its first Level Up event, at the Nashville Fairgrounds on June 30. Chris Jericho rolled up trainer Ron Bass in the semifinal, then beat Marcus Alexander Bagwell with a German suplex for the vacant Power Pro Heavyweight Title (**1/2)."], ["p", "He's 2–0 and one half of the Thrillseekers with Lance Storm, and he's the face of the academy. Michael Modest has been promised the first shot."]], "facts": [["Champion", "Chris Jericho"], ["Semifinal", "d. Ron Bass (roll-up)"], ["Final", "d. Marcus Alexander Bagwell (German suplex)"], ["Rating", "**1/2"], ["Tag", "the Thrillseekers with Lance Storm"]], "factTitle": "The Champion"}, "pp-modest-wants-shot-0630": {"p": "pp", "news": 1, "by": "Newsletter staff", "date": "1991-06-30", "region": "Nashville Report", "kicker": "Power Pro · Nashville Fairgrounds, June 30", "title": "Modest Wants His Shot", "dek": "Michael Modest is 3–0 and confronted the champion. Rocky Johnson promised him the first title shot.", "body": [["p", "Michael Modest won the Genesis tournament with the title not on the line, then beat Simon Diamond again at First Strike with a fisherman suplex (***1/4). After Chris Jericho won the belt, Modest confronted him in the ring."], ["p", "Rocky Johnson, the academy's head trainer and on-air authority, promised Modest the first shot at the new champion. He's 3–0 and has a better record than the man with the belt. When the match happens is To establish."]], "facts": [["Record", "3–0"], ["Genesis", "won the tournament"], ["First Strike", "d. Simon Diamond, fisherman suplex, ***1/4"], ["Promise", "first title shot, from Rocky Johnson"], ["Champion", "Chris Jericho"]], "factTitle": "Michael Modest"}, "pp-power-hour-in-the-can": {"p": "pp", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Nashville Report", "kicker": "Power Pro · Nashville Fairgrounds", "title": "Power Hour Is in the Can", "dek": "Power Pro's third card was taped before the Great American Bash and airs July 28.", "body": [["p", "Power Pro's third card, Power Hour, was taped at the Nashville Fairgrounds before the Great American Bash. It airs on July 28, and the academy is keeping the results to itself until then."], ["p", "What has gotten out is that there are new names around the academy. Who they are, and whether they made the tape, is To establish until it airs."]], "facts": [["Card", "Power Hour, the third Power Pro card"], ["Taped", "Nashville Fairgrounds, before the Bash"], ["Airs", "July 28"], ["Results", "held until air"], ["New faces", "To establish"]], "factTitle": "The Program"}});
